import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Dashboard = ({ token, setToken }) => {
  const [ledgerData, setLedgerData] = useState({
    date: new Date().toISOString().split('T')[0],
    description: '',
    amount: '',
    category: 'expense'
  });
  const [entries, setEntries] = useState([]);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchEntries = async () => {
      try {
        const response = await axios.get('/api/ledger-entries', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setEntries(response.data);
      } catch (error) {
        console.error('Failed to fetch entries:', error);
      }
    };
    fetchEntries();
  }, [token]);

  const handleChange = (e) => {
    setLedgerData({
      ...ledgerData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      const response = await axios.post('/api/submit-ledger', ledgerData, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.anomaly) {
        setMessage({
          type: 'anomaly',
          text: `🚨 ANOMALY DETECTED! ${response.data.message} Authority has been notified via email.`
        });
      } else {
        setMessage({
          type: 'success',
          text: response.data.message
        });
      }

      // Reset form
      setLedgerData({
        date: new Date().toISOString().split('T')[0],
        description: '',
        amount: '',
        category: 'expense'
      });

      // Refresh entries
      const entriesResponse = await axios.get('/api/ledger-entries', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEntries(entriesResponse.data);
    } catch (error) {
      setMessage({
        type: 'error',
        text: error.response?.data?.message || 'Submission failed'
      });
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    setToken(null);
  };

  return (
    <div className="dashboard">
      <div className="dashboard-header">
        <h1>Anomaly Detection System</h1>
        <button onClick={handleLogout} className="logout-btn">
          Logout
        </button>
      </div>

      <div className="ledger-form">
        <h2>Submit Ledger Entry</h2>
        {message && (
          <div className={message.type === 'anomaly' ? 'anomaly-alert' : 
                         message.type === 'success' ? 'success-message' : 'error'}>
            {message.text}
          </div>
        )}
        <form onSubmit={handleSubmit}>
          <div className="form-row">
            <div className="form-group">
              <label>Date:</label>
              <input
                type="date"
                name="date"
                value={ledgerData.date}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label>Category:</label>
              <select
                name="category"
                value={ledgerData.category}
                onChange={handleChange}
                required
              >
                <option value="expense">Expense</option>
                <option value="income">Income</option>
                <option value="transfer">Transfer</option>
                <option value="investment">Investment</option>
                <option value="loan">Loan</option>
                <option value="other">Other</option>
              </select>
            </div>
          </div>
          <div className="form-group">
            <label>Description:</label>
            <textarea
              name="description"
              value={ledgerData.description}
              onChange={handleChange}
              required
              placeholder="Enter transaction description..."
            />
          </div>
          <div className="form-group">
            <label>Amount (₹):</label>
            <input
              type="number"
              step="0.01"
              name="amount"
              value={ledgerData.amount}
              onChange={handleChange}
              required
              placeholder="Enter amount in rupees"
            />
          </div>
          <button type="submit" className="btn" disabled={loading}>
            {loading ? 'Processing...' : 'Submit Entry'}
          </button>
        </form>
      </div>

      <div className="entries-section">
        <h2>Recent Ledger Entries</h2>
        {entries.length === 0 ? (
          <p>No entries found.</p>
        ) : (
          <table className="entries-table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Description</th>
                <th>Amount</th>
                <th>Category</th>
                <th>Status</th>
                <th>Created</th>
              </tr>
            </thead>
            <tbody>
              {entries.map((entry) => (
                <tr key={entry.id}>
                  <td>{entry.date}</td>
                  <td>{entry.description}</td>
                  <td>₹{parseFloat(entry.amount).toLocaleString('en-IN', {minimumFractionDigits: 2})}</td>
                  <td>{entry.category}</td>
                  <td>
                    {entry.is_anomaly ? (
                      <span className="anomaly-badge">ANOMALY</span>
                    ) : (
                      <span className="normal-badge">NORMAL</span>
                    )}
                  </td>
                  <td>{new Date(entry.created_at).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
